import { NextResponse } from 'next/server'
import { requireAdmin } from '../../../../../../src/lib/auth.js'
import { getDb } from '../../../../../../src/lib/db.js'
import { writeAudit } from '../../../../../../src/lib/audit.js'
export async function POST(request,{params}) { try { const admin=await requireAdmin(); const {slug}=await params; const db=getDb(); const client=await db.connect(); try { await client.query('BEGIN'); const page=await client.query('SELECT id FROM cms_pages WHERE page_slug=$1',[slug]); if(!page.rowCount) { await client.query('ROLLBACK'); return NextResponse.json({error:'Page not found.'},{status:404}) }; const fields=await client.query('SELECT id,published_value FROM cms_page_content WHERE page_id=$1',[page.rows[0].id]); for(const field of fields.rows){const number=await client.query('SELECT COALESCE(MAX(revision_number),0)+1 AS value FROM cms_content_revisions WHERE page_content_id=$1',[field.id]); await client.query('INSERT INTO cms_content_revisions (page_content_id,content_value,revision_number,changed_by,change_note) VALUES ($1,$2,$3,$4,$5)',[field.id,field.published_value,number.rows[0].value,admin.id,'Published from Visual CMS']);} const result=await client.query('UPDATE cms_page_content SET published_value=draft_value,updated_by=$2,updated_at=NOW() WHERE page_id=$1 RETURNING id',[page.rows[0].id,admin.id]); await client.query('COMMIT'); await writeAudit({adminId:admin.id,action:'publish',entityType:'cms_page',entityId:page.rows[0].id,newData:{page_slug:slug,fields_published:result.rowCount},request}); return NextResponse.json({data:{published:result.rowCount}}) } catch(error){await client.query('ROLLBACK');throw error} finally{client.release()} } catch { return NextResponse.json({error:'Unable to publish page.'},{status:400})} }
